{
  "segment_function": "argument",
  "claims": [
    {
      "claim": "Value always means value in exchange and is acquired exclusively in the public realm through public esteem rather than through labor, work, capital, or material.",
      "claim_type": "author_position",
      "supporting_excerpt": "value, being “an idea of proportion between the possession of one thing and the possession of another in the conception of man,” “always means value in exchange.” ... This value consists solely in the esteem of the public realm where the things appear as commodities, and it is neither labor, nor work, nor capital, nor profit, nor material, which bestows such value upon an object, but only and exclusively the public realm where it appears to be esteemed, demanded, or neglected.",
      "support_kind": "direct",
      "qualifications": [
        "applies when things appear as commodities in the exchange market"
      ],
      "confidence": 1
    },
    {
      "claim": "The transformation of things into values or commodities necessarily brings about universal relativity and the loss of intrinsic, objective worth independent of changing supply and demand.",
      "claim_type": "author_position",
      "supporting_excerpt": "Universal relativity, that a thing exists only in relation to other things, and loss of intrinsic worth, that nothing any longer possesses an “objective” value independent of the ever-changing estimations of supply and demand, are inherent in the very concept of value itself.",
      "support_kind": "direct",
      "qualifications": [
        "inherent in the very concept of value itself"
      ],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "Value",
      "definition": "The quality a thing acquires automatically the moment it appears in public as a commodity, consisting solely in the esteem of the public realm and determined by exchange relativity rather than intrinsic worth."
    },
    {
      "term": "Intrinsick natural worth",
      "definition": "An objective quality of a thing itself, existing outside the will of the individual purchaser or seller whether they recognize it or not."
    }
  ],
  "distinctions": [
    {
      "item_a": "Marketable value",
      "item_b": "Intrinsic natural worth",
      "distinction": "Marketable value is altered by the alteration of proportion a commodity bears to something else and depends on public esteem in the exchange market, whereas intrinsic worth is an objective quality of the thing itself that can only be changed through the physical alteration of the thing."
    }
  ],
  "examples": [],
  "objections": [],
  "responses": [],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "The distinction between marketable value and intrinsic worth.",
    "The inherent universal relativity and loss of absolute standards tied to the concept of value in exchange."
  ]
}

